  }
  if (window.cabinet && cabinet.onVisibility) cabinet.onVisibility(v => { if (!v && G.state === 'play') pause(); });
  document.addEventListener('visibilitychange', () => { if (document.hidden && G.state === 'play') pause(); });

  addEventListener('resize', A.resize); A.resize();
  let lastT = performance.now(), T = 0;
  function loop(now) {
    requestAnimationFrame(loop);
    const rdt = Math.min(0.1, (now - lastT) / 1000); lastT = now; T += rdt;
    if (!innerWidth || !innerHeight) return;
    if (innerWidth !== A.dims().W || innerHeight !== A.dims().H) A.resize();
    readInput();
    try { A.update(rdt); } catch (e) { console.error(e); }
    A.render(T);
  }
  ui.menu(); requestAnimationFrame(loop);
})(window.App);

files.style.css:
html,body{margin:0;height:100%;overflow:hidden;background:#05040d;color:#eef1ff;font-family:-apple-system,"SF Pro Text",Inter,system-ui,sans-serif;user-select:none;-webkit-user-select:none}
canvas{position:fixed;inset:0;width:100%;height:100%;display:block;outline:none;touch-action:none}
#btns{position:fixed;right:8px;bottom:8px;display:flex;gap:6px;z-index:5}
#btns button{width:30px;height:30px;border-radius:10px;border:1px solid #ffffff22;background:#0d0b22aa;color:#9fe9ff;font-size:12px;cursor:pointer;backdrop-filter:blur(6px)}
#btns button.off{color:#ff5c8a;text-decoration:line-through}
#scr{position:fixed;inset:0;display:none;z-index:4;align-items:center;justify-content:center;flex-direction:column;padding:48px 16px 16px;box-sizing:border-box;background:radial-gradient(ellipse at center,#0a0820aa,#05040ddd)}
#scr.on{display:flex}
.title{font-weight:900;font-size:clamp(34px,11vw,72px);letter-spacing:.04em;line-height:.95;text-align:center;background:linear-gradient(90deg,#3ff6ff,#ff3dc8,#ffd23f,#3ff6ff);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:hue 6s linear infinite,bob 3s ease-in-out infinite;filter:drop-shadow(0 0 12px #ff3dc888) drop-shadow(0 0 24px #3ff6ff55)}
@keyframes hue{to{background-position:300% 0}}
@keyframes bob{50%{transform:translateY(-4px) scale(1.02)}}
.sub{font-size:11px;letter-spacing:.3em;color:#9fa6d8;margin:6px 0 14px;text-transform:uppercase}
.btn{display:block;width:min(240px,80vw);margin:5px auto;padding:11px;border-radius:14px;border:1px solid #3ff6ff55;background:linear-gradient(180deg,#16133acc,#0c0a24cc);color:#e9fbff;font-weight:700;font-size:14px;letter-spacing:.06em;cursor:pointer;transition:transform .12s,box-shadow .2s}
.btn:hover{box-shadow:0 0 18px #3ff6ff55}
.btn:active{transform:scale(.96)}
.btn.big{font-size:18px;padding:14px;border-color:#ff3dc8;box-shadow:0 0 22px #ff3dc866,inset 0 0 12px #ff3dc833}
.cores{font-size:12px;color:#ffd23f;margin-bottom:8px}
.ships{display:flex;gap:6px;margin:4px 0 10px}
.ship{flex:1;min-width:84px;padding:7px 6px;border-radius:12px;border:1px solid #ffffff1a;background:#0e0c26cc;font-size:10px;text-align:center;cursor:pointer;color:#bcc3ee}
.ship b{display:block;font-size:12px;color:#fff;margin-bottom:2px}
.ship.sel{border-color:var(--c);box-shadow:0 0 14px var(--c)}
.ship.lock{opacity:.6}
.hint{font-size:10px;color:#7c82b3;margin-top:10px;text-align:center}
.panel{width:min(320px,92vw);max-height:100%;overflow:auto}
h2{margin:0 0 10px;font-size:18px;text-align:center;letter-spacing:.1em;color:#9ff3ff;text-shadow:0 0 12px #3ff6ff}
.row{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:12px;background:#0f0d28cc;border:1px solid #ffffff12;margin-bottom:6px;font-size:12px}
.row .g{flex:1}.row small{color:#8a90c0;display:block}
.pips{color:#3ff6ff;letter-spacing:2px;font-size:10px}
.buy{padding:6px 10px;border-radius:10px;border:1px solid #ffd23f88;background:#2a2208;color:#ffd23f;font-weight:700;cursor:pointer;font-size:11px}
.buy:disabled{opacity:.35;cursor:default}
.cards{display:flex;flex-direction:column;gap:8px;width:min(320px,92vw)}
.card{position:relative;display:flex;gap:10px;align-items:center;padding:11px 12px;border-radius:14px;background:linear-gradient(135deg,#15123a,#0b0a20);border:1.5px solid var(--r);box-shadow:0 0 16px var(--r),inset 0 0 18px #0008;cursor:pointer;opacity:0;transform:translateY(40px) scale(.9);animation:cin .45s cubic-bezier(.2,1.4,.4,1) forwards;transition:transform .12s}
.card:hover{transform:scale(1.03)!important}
.card:active{transform:scale(.97)!important}
.card .ic{font-size:22px;width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#ffffff0d;color:var(--c);text-shadow:0 0 10px var(--c)}
.card .g{flex:1;font-size:11px;color:#aab0dd}.card b{display:block;font-size:14px;color:#fff}
.card .rr{position:absolute;top:6px;right:10px;font-size:9px;letter-spacing:.15em;color:var(--r);font-weight:800}
.card.epic{animation:cin .45s cubic-bezier(.2,1.4,.4,1) forwards,ep 1.2s ease-in-out infinite alternate}
@keyframes ep{to{box-shadow:0 0 28px var(--r),inset 0 0 18px #0008}}
@keyframes cin{to{opacity:1;transform:none}}
.lvh{font-size:22px;font-weight:900;letter-spacing:.12em;color:#ffd23f;text-shadow:0 0 16px #ffb02e;margin-bottom:10px;animation:bob 1.4s infinite}
.stats{display:grid;grid-template-columns:1fr 1fr;gap:6px;width:min(300px,90vw);margin-bottom:8px}
.stat{background:#0f0d28cc;border:1px solid #ffffff12;border-radius:12px;padding:8px;text-align:center;font-size:10px;color:#8a90c0}
.stat b{display:block;font-size:18px;color:#fff}
.build{font-size:11px;color:#bfc5f0;text-align:center;max-width:300px;margin-bottom:8px;line-height:1.5}
.dead{font-size:30px;font-weight:900;color:#ff3d7f;text-shadow:0 0 18px #ff3d7f;letter-spacing:.1em;margin-bottom:8px}
